<?php require 'config.php';require 'includes/functions.php';$q=$pdo->prepare("SELECT * FROM hospitals WHERE id=? AND active=1");$q->execute([(int)($_GET['id']??0)]);$h=$q->fetch();if(!$h){http_response_code(404);exit('Hospital not found');}$q=$pdo->prepare("SELECT d.id,d.specialty,d.consultation_fee,u.name FROM doctors d JOIN users u ON u.id=d.user_id WHERE d.hospital_id=? AND d.active=1");$q->execute([$h['id']]);$docs=$q->fetchAll();$title=$h['name'];require 'includes/header.php';?><div class="intro"><span class="tag">HOSPITAL PROFILE</span><h1><?=e($h['name'])?></h1><p><?=e($h['address'])?>, <?=e($h['city'])?></p><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=<?=urlencode($h['address'].' '.$h['city'])?>">View on Google Maps</a></div><section class="panel"><h2>Doctors at this hospital</h2><?php foreach($docs as $d):?><p><b>Dr. <?=e($d['name'])?></b> · <?=e($d['specialty'])?> · <?=rupee($d['consultation_fee'])?> · <a href="book.php?doctor=<?=$d['id']?>">Book</a></p><?php endforeach;?></section><?php require 'includes/footer.php';?>